oved AND profile IS NULL;
UPDATE companies SET description='Aftermarket Auto Parts Alliance is headquartered in San Antonio, Texas, and traces its origins to 1978. The organization operates as a cooperative network of independent warehouse distributors rather than a single-owner enterprise; no individual founders are named in public materials. It began as a program to supply auto parts and service support to independent businesses across North America and has since expanded its footprint to include Mexico, Honduras, Colombia, Belize, Europe, and China.

The alliance manages two consumer-facing brands — Auto Value and Bumper to Bumper — under which thousands of parts stores and certified service centers operate. Its core services include warehouse distribution, private-label parts branding (Perfect Stop, Parts Master, Perfect View, MacPherson, Ultra Stop, Auto Body Master), a proprietary electronic ordering platform called MyPlace4Parts, and warranty programs such as Confidence Plus North American Warranty and SafeRoute Roadside Assistance. The network reports approximately 3,500 certified service centers in the United States and Canada, supported by financing options and technical training for members.

Primary customers are independent automotive repair shops, parts retailers, and warehouse distributors within the automotive aftermarket. Member distributors such as Auto-Wares, Hahn Automotive Warehouse, and Superior Automotive Warehouse illustrate the wholesale tier, while certified service centers like Highway 7 Service Center (Iowa) and Ste-Agathe Service Centre (Manitoba) represent the retail-repair tier.

The organization emphasizes service differentiation — encapsulated in the tagline "SERVICE is the difference. We get it!" — and positions itself as a partner that provides tools, training, marketing support, and a collective voice for independents in the aftermarket. Its warranty coverage is honored across all network locations, and the ordering platform is designed to reduce administrative burden for repair shops.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Warehouse distribution", "Parts retail operations", "Certified service center network management", "Private-label parts branding", "Electronic parts ordering (MyPlace4Parts)", "Warranty program administration", "Roadside assistance program", "Member financing programs", "Technical training for technicians", "Marketing and promotional support"], "industries": ["Automotive aftermarket", "Automotive repair and maintenance", "Automotive parts distribution", "Warehouse distribution"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["3,500 certified service centers across the U.S. and Canada", "Confidence Plus North American Warranty honored at all network locations", "MyPlace4Parts electronic ordering platform for repair shops", "Private-label parts lines including Perfect Stop and Ultra Stop", "Global distribution network spanning North America, Central America, Europe, and China"], "facts_used": ["Founded 1978 -> db", "Headquarters San Antonio, Texas -> db", "Network of independent warehouse distributors -> page:/", "Brands: Auto Value, Bumper to Bumper -> page:/", "Private label lines: Perfect Stop, Parts Master, Perfect View, MacPherson, Ultra Stop, Auto Body Master -> page:/", "3,500 certified service centers in US and Canada -> page:/", "MyPlace4Parts ordering platform -> page:/", "Confidence Plus North American Warranty and SafeRoute Roadside Assistance -> page:/", "Global presence: North America, Mexico, Honduras, Colombia, Belize, Europe, China -> page:/", "Languages: English, French, Spanish -> page:/", "Member testimonials from independent repair shops -> page:/"], "company_type": "Distributor / reseller", "makes_products": "no", "type_evidence": "Auto Value and Bumper to Bumper are part of the independent member network of the Aftermarket Auto Parts Alliance, the premier aftermarket distribution and marketing program group in the world. As a network of independent warehouse distributors...", "founded_year": "1978", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": ["English", "French", "Spanish"], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='aftermarket-auto-parts-alliance' AND approved AND profile IS NULL;
UPDATE companies SET description='Aftermarket HQ operates from Las Vegas, Nevada, where it has served the off-road community for over a decade. The shop describes itself as built by enthusiasts for enthusiasts, though the INPUT does not specify an exact founding year or ownership structure. Team members referenced in customer testimonials include Walt, Evan, Vanessa, and Jamie.

The shop provides suspension systems, custom fabrication, and complete off-road builds, along with installation, tuning, and parts sales. Fabrication work includes CNC-machined billet aluminum components such as Starlink mounts, 16-gauge steel brackets with matte fine-textured black powder coating, and 304 stainless steel downpipes. Services extend to ECU flashing, wiring harness integration, and LED lighting installation from brands such as Baja Designs and SwarfWorks. Facility size, headcount, and annual volume are not disclosed.

Customers are primarily off-road enthusiasts driving Ford F-150, Raptor, Super Duty, Bronco, and Ranger platforms. The shop supports desert racing, rock crawling, and trail riding applications, supplying both individual owners and builders seeking turnkey upgrades or à la carte performance parts.

Aftermarket HQ emphasizes that every product is tested in the desert, on rocks, and through trails before it reaches the customer.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom fabrication", "Suspension system installation and tuning", "Complete off-road vehicle builds", "CNC machining of billet aluminum components", "Powder coating (matte fine-textured black outdoor)", "Wiring harness design and installation", "LED lighting system installation", "Starlink mount fabrication and installation", "ECU tuning and flashing", "Performance parts sales and distribution", "304 stainless steel exhaust fabrication", "16-gauge steel bracket fabrication"], "industries": ["Automotive aftermarket", "Off-road performance", "Truck and SUV modification"], "materials": ["16ga steel", "304 stainless steel", "CNC billet aluminum", "Powder coating materials"], "equipment": ["CNC machines", "Powder coating equipment"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Tested in the desert, on the rocks, and through the trails", "Built by enthusiasts, for enthusiasts", "10+ years of hands-on experience in the Las Vegas Valley", "Custom fabrication and complete off-road builds under one roof", "Real-world expertise combined with cutting-edge technology"], "facts_used": ["Location: Las Vegas, Nevada -> db", "10+ years in business -> homepage", "Team members: Walt, Evan, Vanessa, Jamie -> homepage testimonials", "Services: suspension systems, custom fabrication, complete off-road builds, tuning, installation -> homepage", "Materials: 16ga steel, 304SS, CNC billet aluminum, powder coating -> homepage products", "Brands carried: Baja Designs, SwarfWorks, SPD -> homepage", "Platforms: Ford F150, Raptor, Super Duty, Bronco, Ranger -> homepage products", "Custom fabrication of Starlink mounts, brackets, downpipes -> homepage products", "Desert testing claimed -> homepage", "Built by enthusiasts for enthusiasts -> homepage"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Whether it''s suspension systems, custom fabrication, or complete off-road builds, our work speaks for itself \u2014 built by enthusiasts, for enthusiasts.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='aftermarket-hq' AND approved AND profile IS NULL;
UPDATE companies SET description='Agave Semiconductor is a Phoenix, Arizona-based semiconductor company focused on motor control integrated circuits. Its founder has been featured in local business media discussing the Arizona startup ecosystem.

The company designs and supplies Smart-Drive pre-driver ICs for brushless DC fans, offering both open-loop (AGV8011, AGV8012, AGV8018, AGV8019) and closed-loop (AGV8001, AGV8002, AGV8008, AGV8009) product families. These devices implement real-time efficiency optimization algorithms that adjust power delivery to maintain mechanical workload while minimizing electrical input. The AGV8009 closed-loop pre-driver, for example, provides 40 V MOS output pre-drivers capable of sourcing or sinking 100 mA, along with soft-start, current-limit, locked-rotor, and thermal protections.

Primary markets include data-center cooling, where the technology reduces electricity consumed by fans and blowers in server enclosures, as well as broader electronics cooling applications. The company''s literature highlights computer server enclosures as a key environment where the pressure-airflow (PQ) curve intersection determines operating points.

Agave states that its Smart-Drive technology can achieve energy savings of up to 80 percent depending on fan pressure and airflow conditions, while also reducing motor vibration. The differentiation rests on continuous, real-time efficiency optimization that adapts to changing system impedance without sacrificing speed or workload.', certifications=ARRAY['RoHS']::text[], profile='{"capabilities": ["Motor control IC design", "Smart-Drive efficiency optimization algorithms", "Open-loop pre-driver IC development", "Closed-loop pre-driver IC development", "BLDC fan controller design", "Mixed-signal semiconductor design", "Real-time motor efficiency optimization", "Soft-start and protection circuit integration"], "industries": ["Data centers", "Server cooling", "Electronics cooling", "Computer server enclosures"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Headquarters: Phoenix, AZ -> page ''/''", "Product lines: AGV8009, AGV8011, AGV8012, AGV8018, AGV8019, AGV8001, AGV8002, AGV8008 -> page ''/''", "Smart-Drive technology description and energy savings claims -> page ''/''", "Certification: RoHS -> db", "Founder mentioned but not named -> page ''/''", "Data center applications and server enclosure references -> page ''/''", "Closed-loop feedback, soft start, current limit, locked rotor, thermal protections -> page ''/''", "Real-time efficiency optimization and reduced vibration -> page ''/''"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Agave Semiconductor is dedicated to improving electric motor efficiency and performance through intelligent control.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='agave-semiconductor' AND approved AND profile IS NULL;
UPDATE companies SET description='Agri-Industrial Plastics Co. was founded in 1978 by Dick Smith in Fairfield, Iowa. The company began by collaborating with industry leaders to advance plastic blow molding technology.

The company operates a 340,000-square-foot manufacturing facility housing 20 monolayer accumulator-head blow molding machines and eight multilayer continuous coextrusion machines dedicated to producing EPA-compliant, non-automotive fuel tanks. In addition to blow molding, Agri-Industrial provides engineering and design support, assembly, packaging, and quality inspection using a Shape Grabber laser scanner for dimensional verification.

Its customer base spans the turf equipment, power sports, agricultural, and marine sectors, with additional work in lawn and garden and recreational watercraft. Long-standing clients include EXCEL Industries (Hustler Turf Equipment), Kubota Manufacturing of America, and John Deere, all of whom cite the company’s on-time delivery and design collaboration.

Agri-Industrial’s stated vision is to be the provider of innovative, high-quality blow molded solutions. The company emphasizes a systematic quality management system certified to ISO 9001:2015, advanced product quality planning, and Level III PPAP capability as core differentiators.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Custom blow molding", "Extrusion blow molding", "Engineering and design support", "Quality control (ISO 9001:2015)", "Assembly and packaging", "Advanced product quality planning (APQP)", "Production part approval process (PPAP) Level III", "Laser scanning inspection (Shape Grabber)", "Hourly production part inspections"], "industries": ["Turf equipment", "Power sports", "Agricultural", "Marine", "Lawn and garden", "Recreational equipment", "Water craft"], "materials": [], "equipment": ["Monolayer accumulator-head blow molding machines (20)", "Multilayer continuous coextrusion blow molding machines (8)", "Shape Grabber laser scanner"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["EPA-compliant non-automotive fuel tank production", "ISO 9001:2015 certified quality system", "In-house engineering and design support", "Laser scanning for dimensional verification"], "facts_used": ["Founded in 1978 by Dick Smith in Fairfield, Iowa -> db, /about-us", "Family-owned; daughter Lori took over in 2015 -> db", "340,000 sq ft facility with 20 monolayer accumulator-head and 8 multilayer continuous coex machines -> /about-us", "ISO 9001:2015 certified (without Design) by Smithers Quality Assessments -> /quality", "Industries served: turf equipment, power sports, agricultural, marine, lawn & garden, recreational equipment, water craft -> /about-us, /quality", "Customers: EXCEL Industries/Hustler Turf Equipment, Kubota Manufacturing of America, John Deere -> / (homepage testimonials)", "Engineering & design support, assembly & packaging, APQP, PPAP Level III, laser scanning inspection -> /quality, / (homepage)", "Vision statement: ''To be the leading provider of innovative, high quality, blow molded solutions'' -> /about-us", "EPA-compliant non-automotive fuel tanks -> / (homepage), /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Agri-Industrial Plastics is a certified custom industrial blow molder of large scale parts.", "founded_year": "1978", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='agri-industrial-plastics-co' AND approved AND profile IS NULL;
UPDATE companies SET description='Air Metal VA was founded in 1970 by Douglas and Gladys Smith in Richmond, Virginia. The company has served the Central Virginia region for over five decades with custom sheet metal fabrication and metal roofing.

The company runs a full-service fabrication shop capable of handling projects of any size. Its core work includes standing seam roofing panels — snap lock, mechanical lock, and nail strip — as well as 5V crimp roofing, metal soffit and wall panels, fascia, valleys, coping, and drip edge. Air Metal also produces custom gutters, roofing soffits, chimney caps, cupolas, conductor heads, vents, and HVAC components such as ducting, fittings, plenums, diffuser boxes, and register boxes. Historic duplication of architectural metalwork is another specialty.

The shop''s output ranges from standard roofing panels to one-off architectural pieces for historic restoration projects.

The company emphasizes its deep regional experience and the ability to match Virginia''s unpredictable weather with durable, custom-fabricated metal solutions. Its differentiator is the combination of a fully equipped fabrication shop and a team with decades of hands-on expertise, allowing it to turn nearly any project vision into reality.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Sheet metal fabrication", "Metal roofing installation", "Standing seam panel fabrication (snap lock, mechanical lock, nail strip)", "5V Crimp roofing", "Metal soffit panel fabrication", "Wall panel fabrication", "Fascia panel fabrication", "Valley fabrication", "Coping fabrication", "Drip edge fabrication", "Historic duplication", "Custom gutter fabrication", "Roofing soffit fabrication", "Chimney cap fabrication", "Cupola fabrication", "Conductor head fabrication", "Vent fabrication", "HVAC ducting fabrication", "HVAC fitting fabrication", "Plenum fabrication", "Diffuser box fabrication", "Register box fabrication"], "industries": ["Roofing", "Sheet metal fabrication", "Construction", "HVAC"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Full-service fabrication shop handling projects large or small", "Over 60 years of combined fabrication experience", "Specializes in Snaplock, 5V Crimp, and nailstrip standing seam roofing panels", "Custom gutters, soffits, and historic architectural metal duplication", "Produces HVAC ducting, fittings, plenums, and register boxes"], "facts_used": ["Founded in 1970 by Douglas and Gladys Smith -> /about", "Serving Central Virginia region with custom sheet metal & roofing work for over 50 years -> /", "Full-service fabrication shop -> /", "Specializes in Snaplock, 5V Crimp, nailstrip standing seam panels -> /", "Custom gutters, roofing soffits, chimney caps, cupolas, conductor heads, vents -> /", "Produces HVAC ducting, fittings, plenums, diffuser boxes, register boxes -> /", "Over 60 years combined fabrication experience -> /about", "Since 2021 continued legacy of Smiths -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Your full service sheet metal fabricator, and metal roofing experts in Richmond, Virginia.", "founded_year": "1970", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='air-metal-va' AND approved AND profile IS NULL;
UPDATE companies SET description='Link Labs is headquartered in Annapolis, Maryland. The company was founded in 2014 by a group of veteran engineers from the Johns Hopkins University Applied Physics Laboratory, who had previously collaborated on projects for the U.S. Department of Defense, telecommunications firms, and the intelligence community.

The company develops the AirFinder platform, an end-to-end IoT asset visibility system that combines Bluetooth Low Energy, phase ranging, and other location technologies to track assets indoors and outdoors with up to 30-centimeter accuracy. The hardware lineup includes location beacons, asset tags, access points, and gateways, all managed through a cloud-based interface. Link Labs reports processing more than two billion location, condition, and behavior events per month and holds 29 U.S. patents plus additional international patents.

AirFinder serves manufacturing operations, logistics operations, healthcare facilities, and election agencies. Customers use the system to monitor work-in-process inventory, equipment, tools, packages, and personnel in warehouses; track trailers and assets across geographies; ensure compliance for temperature-sensitive shipments; and maintain chain-of-custody for election equipment. Partnerships with Geotab and the Hubble Network extend the platform into telematics and global satellite-based tracking.

The founders built AirFinder to break the cost-performance compromise in asset tracking, aiming to deliver an affordable, scalable solution that integrates multiple location technologies without requiring expensive infrastructure. The company emphasizes low total cost of ownership, from tags and infrastructure to installation and maintenance, and highlights its ability to integrate with existing enterprise systems via MQTT and API.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Real-time asset location tracking (indoor/outdoor)", "Condition monitoring (temperature, humidity, shock, tampering)", "Bluetooth Low Energy (BLE) asset tracking", "Phase ranging for indoor positioning", "Geofencing and zone-based alerting", "Work-in-process (WIP) tracking", "Trailer and fleet tracking", "Personnel tracking", "Cloud-based asset visibility platform", "MQTT and API integration", "Multi-technology location fusion (BLE, GPS, Wi-Fi, cellular)", "Low-power wide-area network (LPWAN) technology", "Sensor integration (BLE sensors)", "Real-time dashboards and reporting", "Custom alerting and notifications", "Asset management software", "RTLS (Real-Time Location System) deployment", "Indoor positioning system (IPS) installation", "Outdoor asset tracking via cellular/satellite", "Supply chain visibility solutions", "Compliance monitoring (FDA, etc.)", "Election equipment tracking", "Healthcare asset tracking", "Manufacturing operations tracking"], "industries": ["Manufacturing", "Logistics", "Healthcare", "Government / Elections"], "materials": [], "equipment": ["Location Beacon", "Asset Tag", "AirFinder Access Point", "Gateway"], "volume": "", "lead_time": "", "tolerances": "Up to 30 cm accuracy", "built_on": ["Tracks over 2 billion IoT location, condition, and behavior events per month", "29 U.S. patents plus international patents", "Up to 30 cm location accuracy indoors and outdoors", "Tags with up to 7-year battery life", "Global 5G connectivity and MQTT/API integratio