ype": "Installer / service company", "makes_products": "no", "type_evidence": "All American Electric is an electrical service company known for five star service located in Greenwood, Delaware.", "founded_year": "2005", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='all-american-electric' AND approved AND profile IS NULL;
UPDATE companies SET description='All Bake Technologies Inc. has operated from Tinton Falls, New Jersey since its founding in 1994. The company positions itself as a specialist in bakery equipment, offering sales, service, and consultation to bakeries of all sizes.

