UPDATE companies SET description='American Electric Components, Inc. was founded in 1995 in Vernon, California, as a family-owned and operated business. The company traces its roots to a multi-generational team that brings over a century of cumulative experience to the design, fabrication, and repair of electrical transformers.

Operating from a 78,400-square-foot property with a 47,000-square-foot shop, AEC maintains complete in-house control over manufacturing, from initial engineering through final testing. The facility produces and refurbishes single- and three-phase dry-type and oil-filled transformers rated up to 10,000 kVA and 69,000 volts, along with reactors, padmounts, saturable current transformers, inverter-duty units, and desalter transformers. A large stock of new, rebuilt, and repaired units is kept on hand for immediate sale or rental.

The company serves utility, industrial, commercial, and desalination customers nationwide. It is a certified repair center for both ABB and General Electric, meaning its technicians are factory-trained and its processes follow original equipment manufacturer standards. Clients range from utilities needing rapid replacement units to industrial plants requiring on-site oil leak repair, electrical testing, and preventive maintenance.

AEC emphasizes end-to-end oversight of the production cycle, adherence to NEMA, ANSI, IEEE, and UL standards, and the ability to deploy field service crews for emergency repairs. The combination of a deep inventory, certified OEM repair credentials, and a legacy of family stewardship is presented as the foundation of its reliability.', certifications=ARRAY['ANSI','NEMA','IEEE','UL']::text[], profile='{"capabilities": ["Custom transformer design and manufacturing", "Transformer repair and rebuilding", "Transformer retrofitting", "On-site field service (oil leak repair, electrical testing, oil sampling, maintenance)", "Transformer rental and immediate sales", "Testing to NEMA, ANSI, IEEE, and UL standards", "Certified OEM repair for ABB and GE equipment"], "industries": ["Utility", "Industrial", "Commercial", "Desalination"], "materials": ["Copper", "Transformer oil"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["In-house design, fabrication, and testing under one roof", "Certified repair center for ABB and General Electric", "Factory-trained technicians following OEM standards", "Large inventory for immediate sale or rental", "Over a century of cumulative team experience"], "facts_used": ["Founded 1995 -> db", "Family-owned and operated -> /", "Headquarters Vernon, California -> db, /", "Facility size 78,400 sq ft property, 47,000 sq ft shop -> /", "Manufactures and repairs transformers up to 10,000 KVA and 69,000 Volts -> /", "Product types: dry, oil, reactors, padmounts, SCTs, inverter duty, desalter -> /", "Inventory for immediate purchase or rent -> /", "Certified repair center for ABB and GE -> /", "Factory-trained technicians, OEM standards -> /", "Standards: NEMA, ANSI, IEEE, UL -> /", "Industries: utility, industrial, commercial, desalination -> /", "In-field services: oil leak repair, electrical tests, oil sampling, maintenance -> /", "Materials: copper windings, transformer oil -> /", "Company type: Manufacturer -> db description"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Manufactures and repairs electrical transformers (single/three-phase, up to 10,000 KVA)", "founded_year": "1995", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='american-electric-components-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='American Home Medical Equipment Co operates from Lemoyne, Pennsylvania, and was founded in 2011. The company is led by CEO John D. Gilbert and CFO Teresa Gilbert.

