UPDATE companies SET description='Ampleon USA Inc. maintains its U.S. office in Smithfield, Rhode Island, as part of a global semiconductor company headquartered in Nijmegen, Netherlands. The firm operates a production site in Cabuyao, Philippines, and supports customers across the Americas through a network of sales representatives covering every U.S. state.

The company designs and manufactures RF power transistors, including gallium‑nitride‑on‑silicon‑carbide (GaN on SiC) HEMTs and silicon LDMOS devices, for 5G massive MIMO base stations, small‑cell and macro‑cell infrastructure, particle accelerators, and industrial heating systems. Its product line spans discrete transistors and integrated modules rated from kilowatts to megawatts.', certifications=ARRAY['ITAR']::text[], profile='{"capabilities": ["RF power transistor design", "GaN on SiC HEMT manufacturing", "LDMOS transistor manufacturing", "5G mMIMO RF front\u2011end solutions", "Particle accelerator RF systems", "Industrial heating RF solutions", "ITAR\u2011compliant manufacturing"], "industries": ["Telecommunications (5G)", "Industrial, Scientific and Medical", "Particle accelerators", "Industrial heating", "Defense"], "materials": ["Gallium Nitride on Silicon Carbide (GaN on SiC)", "Silicon LDMOS"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Market-leading RF power solutions for 5G mMIMO up to 128 simultaneous streams", "High-efficiency small\u2011cell and high\u2011power macro base station transistors", "Solid\u2011state RF power for particle accelerators from kilowatts to megawatts", "GaN on SiC HEMTs for long\u2011pulse high\u2011power applications", "LDMOS discrete transistors for high\u2011power RF designs"], "facts_used": ["Headquarters in Smithfield, RI -> db", "Global headquarters in Nijmegen, Netherlands -> page /", "Production site in Cabuyao, Philippines -> page /", "RF power transistors for 5G mMIMO and base stations -> description", "GaN on SiC HEMT transistors for particle accelerators -> description", "LDMOS discrete transistors for high power -> description", "ITAR certification -> certifications", "Industries served: Industrial, Scientific and Medical -> industries_served", "Sales representative network across U.S. states -> page /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": 